name: Weekly Repo Status Report

on:
  schedule:
    # Runs at 09:00 UTC every Monday
    - cron: '0 9 * * 1'
  workflow_dispatch:
    inputs:
      start_date:
        description: 'Start date of the week (YYYY-MM-DD)'
        required: true
        default: ''
      end_date:
        description: 'End date of the week (YYYY-MM-DD)'
        required: true
        default: ''

permissions:
  contents: read
  issues: read
  pull-requests: read

jobs:
  generate-report:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Calculate Date Range
        id: dates
        run: |
          if [ -z "${{ github.event.inputs.start_date }}" ]; then
            # Default to last Monday if not provided
            START_DATE=$(date -d "last monday" +%Y-%m-%d)
            END_DATE=$(date -d "next sunday" +%Y-%m-%d)
          else
            START_DATE="${{ github.event.inputs.start_date }}"
            END_DATE="${{ github.event.inputs.end_date }}"
          fi
          echo "start_date=$START_DATE" >> $GITHUB_OUTPUT
          echo "end_date=$END_DATE" >> $GITHUB_OUTPUT
          echo "start_ts=$(date -d "$START_DATE" +%s)" >> $GITHUB_OUTPUT
          echo "end_ts=$(date -d "$END_DATE" +%s)" >> $GITHUB_OUTPUT

      - name: Fetch Issues and PRs
        id: fetch_data
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const startTs = parseInt(process.env.START_TS);
            const endTs = parseInt(process.env.END_TS);
            const startDateStr = process.env.START_DATE;
            const endDateStr = process.env.END_DATE;

            // Helper to check if date is within range
            const isInRange = (dateStr) => {
              const d = new Date(dateStr);
              const ts = d.getTime() / 1000;
              return ts >= startTs && ts <= endTs;
            };

            // Fetch Opened Issues
            const openedIssues = [];
            let page = 1;
            while (true) {
              const issues = await github.rest.issues.listForRepo({
                owner: context.repo.owner,
                repo: context.repo.repo,
                state: 'all',
                per_page: 100,
                page: page
              });

              if (issues.data.length === 0) break;

              for (const issue of issues.data) {
                if (issue.pull_request) continue; // Skip PRs
                if (isInRange(issue.created_at)) {
                  openedIssues.push(issue);
                }
              }

              // Optimization: if the oldest issue in this page is older than our start date, we can stop
              const oldestInPage = new Date(issues.data[issues.data.length - 1].created_at).getTime() / 1000;
              if (oldestInPage < startTs) break;

              page++;
            }

            // Fetch Closed Issues
            const closedIssues = [];
            page = 1;
            while (true) {
              const issues = await github.rest.issues.listForRepo({
                owner: context.repo.owner,
                repo: context.repo.repo,
                state: 'closed',
                per_page: 100,
                page: page
              });

              if (issues.data.length === 0) break;

              for (const issue of issues.data) {
                if (issue.pull_request) continue;
                if (isInRange(issue.closed_at)) {
                  closedIssues.push(issue);
                }
              }

              const oldestInPage = new Date(issues.data[issues.data.length - 1].closed_at).getTime() / 1000;
              if (oldestInPage < startTs) break;

              page++;
            }

            // Fetch Merged PRs
            const mergedPRs = [];
            page = 1;
            while (true) {
              const prs = await github.rest.pulls.list({
                owner: context.repo.owner,
                repo: context.repo.repo,
                state: 'closed',
                per_page: 100,
                page: page
              });

              if (prs.data.length === 0) break;

              for (const pr of prs.data) {
                if (pr.merged_at && isInRange(pr.merged_at)) {
                  mergedPRs.push(pr);
                }
              }

              const oldestInPage = prs.data[prs.data.length - 1].merged_at ? 
                new Date(prs.data[prs.data.length - 1].merged_at).getTime() / 1000 : 0;
              if (oldestInPage < startTs) break;

              page++;
            }

            // Group Opened Issues by Label (Skill)
            const openedBySkill = {};
            for (const issue of openedIssues) {
              const labels = issue.labels.map(l => l.name);
              // Heuristic: Look for labels starting with 'skill:' or similar, or default to 'uncategorized'
              // Based on the prompt, skills are like 'azure-prepare', 'extension'.
              // Let's assume labels contain the skill name or we use a specific label format.
              // For this generic script, we will look for labels that match known skills or use the first label.
              // A more robust approach for this specific repo might be needed, but we'll try to extract from labels.
              let skill = 'uncategorized';
              for (const label of labels) {
                if (label.startsWith('skill:')) {
                  skill = label.replace('skill:', '').trim();
                  break;
                }
                // Fallback: if label is exactly the skill name
                if (['azure-prepare', 'azure-deploy', 'extension'].includes(label)) {
                  skill = label;
                  break;
                }
              }

              if (!openedBySkill[skill]) openedBySkill[skill] = [];
              openedBySkill[skill].push(issue);
            }

            // Group Closed Issues by Label (Skill)
            const closedBySkill = {};
            for (const issue of closedIssues) {
              const labels = issue.labels.map(l => l.name);
              let skill = 'uncategorized';
              for (const label of labels) {
                if (label.startsWith('skill:')) {
                  skill = label.replace('skill:', '').trim();
                  break;
                }
                if (['azure-prepare', 'azure-deploy', 'extension'].includes(label)) {
                  skill = label;
                  break;
                }
              }

              if (!closedBySkill[skill]) closedBySkill[skill] = [];
              closedBySkill[skill].push(issue);
            }

            // Format Output
            let report = `## 🌟 Weekly Repo Status — ${startDateStr}–${endDateStr}\n\n`;
            report += `What an outstanding week! The team shipped **${mergedPRs.length} merged PRs**, tackled **${closedIssues.length} closed issues**, and delivered a brand-new skill alongside major infrastructure upgrades. Here's the full picture. 🚀\n\n`;

            report += `## 📊 Issues This Week\n\n`;

            // Opened Issues
            report += `### Issues Opened: ${openedIssues.length}\n\n`;
            report += `| Skill | Count | Issues |\n`;
            report += `|-------|-------|--------|\n`;

            for (const [skill, issues] of Object.entries(openedBySkill).sort((a,b) => b[1].length - a[1].length)) {
              const issueLinks = issues.map(i => `[#${i.number}](https://github.com/${context.repo.owner}/${context.repo.repo}/issues/${i.number})`).join(' ');
              report += `| ${skill} | ${issues.length} | ${issueLinks} |\n`;
            }

            report += `\n### Issues Closed: ${closedIssues.length}\n\n`;
            report += `| Skill | Issues |\n`;
            report += `|-------|--------|\n`;

            for (const [skill, issues] of Object.entries(closedBySkill).sort((a,b) => b[1].length - a[1].length)) {
              const issueLinks = issues.map(i => `[#${i.number}](https://github.com/${context.repo.owner}/${context.repo.repo}/issues/${i.number})`).join(' ');
              report += `| ${skill} | ${issueLinks} |\n`;
            }

            // Save to file
            require('fs').writeFileSync('weekly-report.md', report);

            // Also set output for potential comment creation
            core.setOutput('report', report);

      - name: Create or Update Issue
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const report = fs.readFileSync('weekly-report.md', 'utf8');
            const startDate = process.env.START_DATE;
            const endDate = process.env.END_DATE;
            const title = `Weekly Repo Status — ${startDate}–${endDate}`;

            // Check if issue already exists
            const existingIssues = await github.rest.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'all',
              labels: 'weekly-report'
            });

            let issue;
            const existing = existingIssues.data.find(i => i.title === title);

            if (existing) {
              // Update existing
              await github.rest.issues.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: existing.number,
                body: report
              });
              console.log(`Updated issue #${existing.number}`);
            } else {
              // Create new
              const response = await github.rest.issues.create({
                owner: context.repo.owner,
                repo: context.repo.repo,
                title: title,
                body: report,
                labels: ['weekly-report']
              });
              console.log(`Created issue #${response.data.number}`);
            }
        env:
          START_DATE: ${{ steps.dates.outputs.start_date }}
          END_DATE: ${{ steps.dates.outputs.end_date }}
          START_TS: ${{ steps.dates.outputs.start_ts }}
          END_TS: ${{ steps.dates.outputs.end_ts }}
